int handle_netlink_dump(struct sock *sk) {
    struct sk_buff *skb = NULL;
    int err = 0;

    mutex_lock(&sk->sk_lock);

    if (sk->sk_callback_running) {
        err = -EBUSY;
        goto out;
    }

    if (skb_queue_len(&sk->sk_receive_queue) >= sk->sk_rcvbuf) {
        err = -ENOBUFS;
        goto out;
    }

    skb = alloc_skb(sk->sk_sndbuf, GFP_KERNEL);
    if (!skb) {
        err = -ENOMEM;
        goto out;
    }

    sk->sk_callback_running = 1;

    err = sk->sk_dump(skb);
    if (err < 0) {
        kfree_skb(skb);
        sk->sk_callback_running = 0;
        goto out;
    }

    if (sk->sk_filter && skb_filter(skb, sk->sk_filter)) {
        skb_queue_tail(&sk->sk_receive_queue, skb);
    } else {
        kfree_skb(skb);
    }

    sk->sk_callback_running = 0;

out:
    mutex_unlock(&sk->sk_lock);
    return err;
}
